def solve(inp):
    H,W=len(inp),len(inp[0])
    seen=[[False]*W for _ in range(H)]; objs=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c] and not seen[r][c]:
                col=inp[r][c]; q=[(r,c)]; seen[r][c]=True; cells=[]
                while q:
                    y,x=q.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and inp[ny][nx]==col:
                            seen[ny][nx]=True; q.append((ny,nx))
                objs.append((sorted(cells), col))
    objs.sort(key=lambda t:(-max(r for r,c in t[0]), -max(c for r,c in t[0])))
    occ=set(); out=[[0]*W for _ in range(H)]
    for o,col in objs:
        cur=list(o)
        while True:
            nxt=[(r,c+1) for r,c in cur]
            if any(c>=W for r,c in nxt) or any(p in occ for p in nxt): break
            cur=nxt
        for r,c in cur: out[r][c]=col; occ.add((r,c))
    return out

